  }
}

fn max_count_value(xs: List[Int], candidates: List[Int]) -> Int
  requires len(candidates) > 0
  ensures contains(candidates, result)
  ensures forall c in candidates: count(xs, result) >= count(xs, c)
  effects pure
  example max_count_value([1, 2, 2, 3], [1, 2, 3]) == 2
  example max_count_value([5], [5]) == 5
{
  match candidates {
    [] => 0
    [h, ..t] => match t {
      [] => h
      [_, .._] =>
        if count_occ(xs, h) >= count_occ(xs, max_count_value(xs, t))
        then h
        else max_count_value(xs, t)
    }
  }
}

