  example most_frequent([]) == None
  example most_frequent([5]) == Some(5)
  example most_frequent([1, 1, 2, 3, 3, 3]) == Some(3)
{
  match xs {
    [] => None
    [h, ..t] => Some(max_count_value(xs, xs))
  }
}

