    [] => true
    [h, ..t] => x >= h and ge_all(x, t)
  }
}

fn max_of(xs: List[Int]) -> Option[Int]
  requires true
  ensures (len(xs) == 0 and result == None) or (len(xs) > 0 and exists m in xs: (result == Some(m) and ge_all(m, xs)))
  effects pure
  example max_of([]) == None
  example max_of([3]) == Some(3)
  example max_of([3, 9, 1]) == Some(9)
{
  match xs {
    [] => None
    [h, ..t] => match max_of(t) {
      None => Some(h)
      Some(m) => if h >= m then Some(h) else Some(m)
    }
  }
}

