  requires contains(xs, v)
  ensures len(result) == len(xs) - 1
  ensures forall x in result: contains(xs, x)
  ensures count(result, v) == count(xs, v) - 1
  effects pure
  example remove_value([3, 9, 1], 9) == [3, 1]
  example remove_value([5], 5) == []
{
  match xs {
    [] => []
    [h, ..t] => if h == v then t else [h] ++ remove_value(t, v)
  }
}

fn second_largest(xs: List[Int]) -> Option[Int]
