  example zip_sum([-1, 0], [1, 0]) == [0, 0]
{
  match xs {
    [] => []
    [h, ..t] => match ys {
      [] => []
      [h2, ..t2] => [h + h2] ++ zip_sum(t, t2)
    }
  }
}

